start.filterFormula:
/* If Account Type is changed from an accelerated values to an agency value while the Account Status is open, run the flow */
AND(
         {!$Record.Account_Status__c} = 'open',
         ISCHANGED({!$Record.Type}),
          OR(
                   ISPICKVAL({!$Record__Prior.Type}, 'Accelerated-AGP'),
                   ISPICKVAL({!$Record__Prior.Type}, 'Accelerated-AGP Premier')
           ),
           OR(
                    ISPICKVAL({!$Record.Type}, 'Core'),
                    ISPICKVAL({!$Record.Type}, 'Starter')
             )
)
